+    h: opts.h ?? 0.55,
+    fontFace: theme.font,
+    fontSize: opts.size ?? 24,
+    bold: true,
+    color: opts.color ?? theme.ink,
+    fit: 'shrink',
+    margin: 0,
+    breakLine: false,
+  });
