+    y: opts.y ?? 0.95,
+    w: opts.w ?? 8.6,
+    h: opts.h ?? 0.28,
+    fontFace: theme.font,
+    fontSize: opts.size ?? 9.5,
+    color: opts.color ?? theme.muted,
+    margin: 0,
+    fit: 'shrink',
+  });
+}
+
+function pill(slide, text, x, y, w, theme, fill, color = theme.ink) {
