const { addPage, title, subtitle, card, addFooterSource } = require('./helpers');

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.ink };
  title(slide, "Key Takeaways: AI Coding Agents Are GitHub's Hottest Category", theme, { size: 22, color: 'FFFFFF' });
  subtitle(slide, 'Strategic implications for developer tooling investment and community programs.', theme, { color: theme.textOnDark });
  const takeaways = [
    ['AI agent dominance', '14 of the top 20 repos are AI coding agent tools, skills, or related resources.'],
    ['Claude Code ecosystem explosion', 'At least 7 repos are Claude Code skills, guides, best-practice collections, or multi-tool switchers.'],
    ['Python leads; TypeScript follows', 'Python powers 35% of repos while TypeScript accounts for 20%.'],
    ['Community activity is concentrated', 'hermes-agent alone attracted 78 PRs in 24 hours; 8 repos have zero PRs.'],
    ['Token efficiency is hot', 'caveman and rtk focus on reducing LLM token consumption, including 60–90% for rtk.'],
  ];
  takeaways.forEach((t, i) => {
    const x = i < 3 ? 0.72 : 5.12;
    const y = i < 3 ? 1.32 + i * 0.9 : 1.76 + (i - 3) * 1.02;
    card(slide, x, y, 3.95, 0.62, theme, 'FFFFFF');
    slide.addShape('ellipse', { x: x + 0.18, y: y + 0.19, w: 0.22, h: 0.22, fill: { color: theme.gold }, line: { color: theme.gold, transparency: 100 } });
