  });
  slide.addShape('roundRect', { x: 5.12, y: 4.02, w: 3.95, h: 0.56, rectRadius: 0.08, fill: { color: theme.accent }, line: { color: theme.accent, transparency: 100 } });
  slide.addText('Strategic read: AI coding assistance is no longer a niche subcategory; it is the dominant organizing theme in this 24-hour GitHub trend window.', { x: 5.38, y: 4.2, w: 3.42, h: 0.16, fontFace: theme.font, fontSize: 6.7, bold: true, color: 'FFFFFF', margin: 0, fit: 'shrink' });
  addFooterSource(slide, theme, 'Source: OSSInsight trending repositories brief and key findings');
  addPage(slide, 8, theme, true);
}

module.exports = { createSlide };

